class QuestLog {
    constructor() {
        this.activeQuests = [];
    }

    addQuest(name) {
        this.activeQuests.push({ name, completed: false });
    }

    completeQuest(name) {
        const quest = this.activeQuests.find(q => q.name === name);
        if (quest) quest.completed = true;
    }

    getQuests() { 
        return this.activeQuests; 
    }
}

